export function getTechSvgPath(id: string): string {
  const normalized = id.toLowerCase().trim().replace(/[^a-z0-9]/g, '')
  return TECH_SVG_PATHS[normalized] || TECH_SVG_PATHS[id] || DEFAULT_TECH_SVG_PATH
}
